"""PR branch, title and body, generated by code from the guarded diff.

This repo is public. Nothing the model wrote as free text (summary, root cause,
evidence, findings) may appear here. The inputs are: the class name (an enum),
the app directory (validated against a pattern and against the checkout), field
paths and values read from the real files, and one numeric metric per class.
That metric is reported by the agent, not measured by code, and the PR says so.
"""
from .yamldiff import MISSING

CLASS_TEXT = {
    "oom-memory-limit": (
        "raise memory limit above reported peak",
        "The container was OOMKilled. The new limit is at least 1.2x the peak working-set memory "
        "the agent reported and at most 2x the previous limit. Basis: `.claude/rules/kyverno.md` "
        "(every container needs a memory limit) and `.claude/rules/storage.md` (size from measured "
        "need, never from a default).",
    ),
    "cpu-throttle-limit": (
        "remove the CPU limit that is throttling it",
        "The container was CPU-throttled by its limit. This removes `resources.limits.cpu` and keeps "
        "the request. Basis: `.claude/rules/kyverno.md`: a CPU limit is deliberately not required on "
        "this cluster, because throttling degrades latency-sensitive workloads and cannot protect a "
        "node the way a memory limit does.",
    ),
    "renovate-breakage": (
        "pin back to the last known-good version",
        "A version bump left this resource failing. This changes one version, tag or image value "
        "back to the value it held immediately before the current one in this file's git history. "
        "It never introduces a new version or skips back more than one step.",
    ),
}
REQUIRED_METRIC = {"oom-memory-limit": "peak_memory_bytes", "cpu-throttle-limit": "throttled_ratio",
                   "renovate-breakage": None}


def _cell(v) -> str:
    if v is MISSING:
        return "(removed)"
    return str(v).replace("|", "\\|").replace("`", "'").replace("\n", " ")[:200]


def app_name(app_dir: str) -> str:
    return app_dir.rstrip("/").split("/")[-2]      # clusters/vollminlab-cluster/<ns>/<app>/app


def branch(cls: str, fp12: str) -> str:
    return f"fix/triage-{cls}-{fp12}"


def title(cls: str, app_dir: str) -> str:
    return f"fix({app_name(app_dir)}): {CLASS_TEXT[cls][0]} (triage)"


def body(cls: str, changes: list, metrics: dict, fp12: str) -> str:
    lines = [f"Opened automatically by the triage agent for failure class `{cls}`.", "",
             CLASS_TEXT[cls][1], "",
             "| File | Field | Old | New |", "|---|---|---|---|"]
    lines += [f"| `{_cell(c.file)}` | `{_cell(c.field)}` | `{_cell(c.old)}` | `{_cell(c.new)}` |" for c in changes]
    metric = REQUIRED_METRIC[cls]
    if metric and metric in metrics:
        lines += ["", "| Agent-reported | Value |", "|---|---|", f"| `{metric}` | {float(metrics[metric]):g} |"]
    footer = "This description was generated by code from the parsed diff."
    if metric and metric in metrics:
        footer += (" The one number in the metric table was reported by the agent, not measured by "
                   "code; it is bounded only by the gate's 2x cap on the change.")
    lines += ["", f"Fingerprint: `fp/{fp12}`", "",
              footer + " The full diagnosis is in the private triage-reports issue with the same "
              "fingerprint. A human reviews and merges."]
    return "\n".join(lines)
